grammar G {
token Z = ADAPTER('zzz.word', version=1)
@root @mapping(Root, params=[value]) Start ::= Missing @value;
}

grammar G {
token Z = ADAPTER('zzz.word', version=1)
@root @mapping(Root, params=[value, other]) Start ::= 'x' @value;
}

grammar G {
@whitespace: nope
token Z = ADAPTER('zzz.word', version=1)
@root @mapping(Root, params=[value]) Start ::= 'x' @value;
}

grammar G {
@comment: bad
token Z = ADAPTER('zzz.word', version=1)
@root @mapping(Root, params=[value]) Start ::= 'x' @value;
}

grammar G {
@ubnf: v2
@feature: nope
@tokenContract: { token: 'T' accepts: 'x' failure: 'no-consume' consumes: 'always' context: 'bad' }
token T = ADAPTER('missing.word', version=1)
@root @mapping(Root, params=[value]) Start ::= 'x' @value;
}
